import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.BJFNwp4n.js";const u=JSON.parse('{"title":"Kafka Verification with a Golang Project","description":"","frontmatter":{},"headers":[],"relativePath":"en/open-source/kafka/golang-verification.md","filePath":"en/open-source/kafka/golang-verification.md"}'),n={name:"en/open-source/kafka/golang-verification.md"};function i(d,e,r,c,l,p){return a(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794524635000"},[...e[0]||(e[0]=[o(`<h1 id="kafka-verification-with-a-golang-project" tabindex="-1">Kafka Verification with a Golang Project <a class="header-anchor" href="#kafka-verification-with-a-golang-project" aria-label="Permalink to &quot;Kafka Verification with a Golang Project&quot;">​</a></h1><p>Continuing from <a href="./introduction.html">part one: Kafka in brief, and running it locally</a> — or back to the <a href="./">series index</a>. The cluster is up; this page answers a different question: <strong>how do we prove it really works, not just that the port accepts connections?</strong></p><p>The demo lives at <a href="https://github.com/zq-xu/zq-xu.github.io/tree/master/public/demos/kafka" target="_blank" rel="noreferrer"><code>public/demos/kafka</code></a> in this site&#39;s repository. It is a cobra CLI: every basic capability has its own subcommand, every subcommand runs and asserts on its own, and <code>e2e</code> chains seven steps into one regression command.</p><h2 id="the-idea-behind-the-checks" tabindex="-1">The idea behind the checks <a class="header-anchor" href="#the-idea-behind-the-checks" aria-label="Permalink to &quot;The idea behind the checks&quot;">​</a></h2><p>&quot;Connects successfully&quot; is only the first layer. The interesting parts are the things that break quietly:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Command</th><th>Evidence</th></tr></thead><tbody><tr><td>Cluster metadata and controller readiness</td><td><code>health</code></td><td>Measured <code>RefreshMetadata</code> latency, broker count, controller ID</td></tr><tr><td>A created topic becomes visible</td><td><code>topic create</code> + <code>describe</code></td><td>Polled partition count, leader and ISR readable</td></tr><tr><td>Records actually reach disk</td><td><code>produce</code> (sync)</td><td>Partition and offset returned by the broker</td></tr><tr><td>Key-to-partition mapping is stable</td><td><code>produce</code> + <code>describe</code></td><td>The same key lands on the same partition every time</td></tr><tr><td>Reading by offset without a group</td><td><code>consume</code></td><td>Records read from <code>--partition</code> / <code>--offset</code>, no offsets committed</td></tr><tr><td>Group assignment and offset commits</td><td><code>group</code> + <code>lag</code></td><td>Lag drops after the commit</td></tr><tr><td>The limit is exact, not approximate</td><td><code>group --limit N</code></td><td>Exactly N offsets committed</td></tr><tr><td>The whole chain is repeatable</td><td><code>e2e</code></td><td>Seven assertions all <code>[PASS]</code></td></tr></tbody></table><p><strong>Why a Go project instead of a few CLI commands</strong>: CLI tools cannot verify <em>when</em> offsets are committed, whether consumption continues after a rebalance, or how the limit interacts with <code>MarkMessage</code>. Code turns those into assertions that can be re-run after every change with one command.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th></tr></thead><tbody><tr><td>Kafka</td><td>Started as described in part one; <code>docker ps</code> shows <code>kafka-demo</code> as <code>healthy</code></td></tr><tr><td>Go</td><td>1.25+ (the module declares <code>go 1.25.0</code>)</td></tr><tr><td>Dependencies</td><td><code>github.com/IBM/sarama v1.60.2</code>, <code>github.com/spf13/cobra v1.10.2</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/zq-xu/zq-xu.github.io.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zq-xu.github.io/public/demos/kafka</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre></div><p>All commands below run in that directory.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/kafka.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # if it is not running yet (waits for healthy)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # connectivity</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> produce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --messages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # seven end-to-end assertions</span></span></code></pre></div><p>Or use the Make shortcuts: <code>make kafka-up</code>, <code>make health</code>, <code>make produce</code>, <code>make e2e</code>, <code>make help</code>.</p><h2 id="project-layout" tabindex="-1">Project layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public/demos/kafka/</span></span>
<span class="line"><span>├── main.go                     # entry point, only calls cmd.Execute()</span></span>
<span class="line"><span>├── cmd/                        # command layer, one file per subcommand</span></span>
<span class="line"><span>│   ├── root.go                 #   root: binds global flags + wires the tree</span></span>
<span class="line"><span>│   ├── health.go  produce.go  consume.go</span></span>
<span class="line"><span>│   ├── group.go   lag.go  groups.go  e2e.go</span></span>
<span class="line"><span>│   └── topic/                  #   the topic group lives in its own package</span></span>
<span class="line"><span>│       ├── topic.go            #   parent command: wiring only</span></span>
<span class="line"><span>│       ├── create.go  list.go  describe.go  config.go  delete.go</span></span>
<span class="line"><span>├── internal/</span></span>
<span class="line"><span>│   ├── cli/                    # command plumbing: flags, topic resolution, clients</span></span>
<span class="line"><span>│   │   └── cli.go</span></span>
<span class="line"><span>│   ├── kafkax/                 # Kafka client wrapper, no printing</span></span>
<span class="line"><span>│   │   ├── config.go           #   Options / SaramaConfig / NewClient(With) / NewAdmin</span></span>
<span class="line"><span>│   │   ├── error.go            #   wrap: consistent error prefixes</span></span>
<span class="line"><span>│   │   ├── topic.go            #   list/create/wait/describe/delete/config</span></span>
<span class="line"><span>│   │   ├── produce.go          #   ProduceOptions, message builder, sync/async produce</span></span>
<span class="line"><span>│   │   ├── consumer.go         #   GroupHandler, ConsumeGroup</span></span>
<span class="line"><span>│   │   ├── partition_consume.go#   direct partition reads (no group)</span></span>
<span class="line"><span>│   │   ├── lag.go              #   per-partition and total lag</span></span>
<span class="line"><span>│   │   └── format.go           #   message printing, offset parsing</span></span>
<span class="line"><span>│   └── verify/                 # the 7 assertions, one file per step</span></span>
<span class="line"><span>│       ├── e2e.go              #   Run: executes the steps in order</span></span>
<span class="line"><span>│       ├── run.go              #   shared state + step list</span></span>
<span class="line"><span>│       ├── checker.go          #   assertion tally and [PASS]/[FAIL]</span></span>
<span class="line"><span>│       ├── stats.go            #   consume statistics snapshot</span></span>
<span class="line"><span>│       ├── step_connect.go  step_topic.go  step_produce.go</span></span>
<span class="line"><span>│       ├── step_consume.go  step_offsets.go  step_cleanup.go</span></span>
<span class="line"><span>├── scripts/kafka.sh            # docker run cluster management</span></span>
<span class="line"><span>├── Makefile</span></span>
<span class="line"><span>├── go.mod                      # go 1.25.0 + sarama v1.60.2 + cobra v1.10.2</span></span>
<span class="line"><span>└── go.sum</span></span></code></pre></div><p>Directories and responsibilities line up one to one:</p><table tabindex="0"><thead><tr><th>Directory</th><th>Owns</th><th>Does not</th></tr></thead><tbody><tr><td><code>cmd/</code> (including <code>cmd/topic/</code>)</td><td>Flag parsing, output format, exit codes; one file per subcommand</td><td>Touch Kafka protocol details, assert anything</td></tr><tr><td><code>internal/cli/</code></td><td>Command plumbing: global flag binding, client helpers (<code>WithClient</code> / <code>WithAdmin</code>), topic name resolution</td><td>Hold business logic, print</td></tr><tr><td><code>internal/kafkax/</code></td><td>All Kafka interaction: config, produce, consume, topics, lag; returns data and errors only</td><td>Print, decide exit codes</td></tr><tr><td><code>internal/verify/</code></td><td>The seven-step assertion flow: state, assertion tally, one file per step</td><td>Call sarama directly; goes through <code>kafkax</code> only</td></tr></tbody></table><p>Why this pays off: changing the output format touches only <code>cmd</code>; reusing a capability means calling <code>kafkax</code> directly; and <code>e2e</code> uses exactly the same wrappers as the subcommands — so <strong>e2e passing means every capability the subcommands rely on passes.</strong></p><p>Some deliberate conventions:</p><ul><li><strong>one file per subcommand</strong>; a command with children (<code>topic</code>) becomes its own package <code>cmd/topic</code>, so the parent only wires and root does not grow with every feature;</li><li><strong>each command keeps its flags in its own struct</strong> (<code>produceFlags</code>, ...) instead of package-level variables, so commands cannot leak state into each other;</li><li><strong>no function longer than 50 lines</strong>: long flows are split per step;</li><li><strong>no repeated connection boilerplate</strong>: <code>cli.WithClient</code> / <code>cli.WithAdmin</code> open and close clients;</li><li><strong>local config through a tweak function</strong>: <code>NewClientWith(g, func(c *sarama.Config){...})</code> changes only the line it needs.</li></ul><h2 id="command-overview" tabindex="-1">Command overview <a class="header-anchor" href="#command-overview" aria-label="Permalink to &quot;Command overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>health</code></td><td>Connectivity: brokers / controller / topic count</td></tr><tr><td><code>topic create [name]</code></td><td>Create a topic (partitions, replicas, retention, cleanup policy)</td></tr><tr><td><code>topic list</code></td><td>Topic list (partitions, replicas, internal or not)</td></tr><tr><td><code>topic describe [name]</code></td><td>Partition leaders / replicas / ISR / offset ranges / record count</td></tr><tr><td><code>topic config [name]</code></td><td>Effective config plus its source (<code>--keys all</code> for everything)</td></tr><tr><td><code>topic delete [name]</code></td><td>Delete a topic</td></tr><tr><td><code>produce</code></td><td>Produce records; <code>--async</code> for async, <code>--keys</code> to control key rotation</td></tr><tr><td><code>consume</code></td><td>Read directly by <code>--partition</code> / <code>--offset</code>, without joining a group</td></tr><tr><td><code>group</code></td><td>Consume as a group; exact <code>--limit</code>, <code>--manual-commit</code> for manual commits</td></tr><tr><td><code>lag</code></td><td>Per-partition and total lag</td></tr><tr><td><code>groups</code></td><td>Group list with state and member count</td></tr><tr><td><code>e2e</code></td><td>Seven end-to-end assertions</td></tr></tbody></table><h2 id="what-each-subcommand-verifies-and-why" tabindex="-1">What each subcommand verifies and why <a class="header-anchor" href="#what-each-subcommand-verifies-and-why" aria-label="Permalink to &quot;What each subcommand verifies and why&quot;">​</a></h2><h3 id="health" tabindex="-1"><code>health</code> <a class="header-anchor" href="#health" aria-label="Permalink to &quot;\`health\`&quot;">​</a></h3><p>Verifies that brokers are discoverable, the metadata API works (evidenced by the measured <code>RefreshMetadata</code> latency), the controller is ready, and how many topics exist.</p><p><strong>Why</strong>: every other command depends on metadata; checking it separately immediately separates &quot;cannot connect&quot; from &quot;the code has a bug&quot;.</p><blockquote><p>Trap: sarama connects lazily, so <code>Broker.Connected()</code> stays <code>false</code> until a request has been sent. Printing it directly would mislead. Hence the evidence is &quot;metadata refresh succeeded, and how long it took&quot;.</p></blockquote><h3 id="topic-create-list-describe-config-delete" tabindex="-1"><code>topic create / list / describe / config / delete</code> <a class="header-anchor" href="#topic-create-list-describe-config-delete" aria-label="Permalink to &quot;\`topic create / list / describe / config / delete\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Subcommand</th><th>Verifies</th><th>Why</th></tr></thead><tbody><tr><td><code>create</code></td><td>Creation works and the topic is <strong>really visible</strong></td><td>Creation is asynchronous: <code>CreateTopic</code> succeeding does not mean it can be described, so <code>WaitTopicVisible</code> polls</td></tr><tr><td><code>create</code></td><td>Duplicate creation is rejected</td><td>Idempotence guard, so re-running scripts does not mislead</td></tr><tr><td><code>list</code></td><td>Topics with partition and replica counts</td><td>Answers &quot;which topic do I produce to&quot; and &quot;does it already exist&quot;</td></tr><tr><td><code>describe</code></td><td>Partitions, leaders, ISR, earliest/latest offsets</td><td><strong>Tells whether records really landed</strong>: only a rising latest offset proves it</td></tr><tr><td><code>describe</code></td><td>Record count = latest − earliest</td><td>Shows volume and whether partitions are balanced</td></tr><tr><td><code>config</code></td><td>Effective values and their source</td><td>Debugs &quot;why did my config change not apply&quot;: topic override or broker default</td></tr><tr><td><code>delete</code></td><td>Deletion works and leaves other topics alone</td><td>Cleans up, and verifies the request path</td></tr></tbody></table><p>An empty ISR in <code>describe</code> is a strong signal: the leader has no in-sync replica and writes will fail — in production that is the eve of an incident.</p><p>Three details on <code>create</code> and <code>describe</code>:</p><ul><li><code>--retention</code> takes a Go duration (<code>24h</code>, <code>168h</code> = 7 days by default) and still writes <code>retention.ms</code> underneath;</li><li><code>--cleanup</code> accepts <code>delete</code> / <code>compact</code> / <code>compact,delete</code>;</li><li>before reading offsets, <code>describe</code> refreshes the topic metadata: a topic created a moment ago has no partition leader in the client cache yet, and the request would fail with &quot;not the leader&quot;.</li></ul><h3 id="produce" tabindex="-1"><code>produce</code> <a class="header-anchor" href="#produce" aria-label="Permalink to &quot;\`produce\`&quot;">​</a></h3><p>Verifies: writes succeed (in sync mode the broker-returned partition/offset is hard evidence); the same key keeps the same partition; whether partitions are balanced; the throughput difference between sync and async.</p><p><strong>Why</strong>: counting &quot;how many I sent&quot; means nothing; only <code>Successes()</code> means the broker accepted them. Key-to-partition mapping is the basis of ordering — if the same key jumps partitions, &quot;ordered by order ID&quot; is broken. Comparing sync and async on the same payload shows what batching buys.</p><p>Three keys may land on only two partitions (hashing is not uniform); <code>partition 2 -&gt; 0 records</code> is normal.</p><h3 id="consume" tabindex="-1"><code>consume</code> <a class="header-anchor" href="#consume" aria-label="Permalink to &quot;\`consume\`&quot;">​</a></h3><p>Verifies reading by partition and from a chosen position, printing partition/offset/key/headers/value to check order, stopping at the limit without committing offsets.</p><p><strong>Why it exists</strong>: proves reading does not depend on a consumer group — an offset is just a number, and any position can be read; it is the tool for &quot;is this record there?&quot;; and because it commits nothing, it is a <strong>read-only safe operation</strong> that can be repeated without changing state.</p><h3 id="group" tabindex="-1"><code>group</code> <a class="header-anchor" href="#group" aria-label="Permalink to &quot;\`group\`&quot;">​</a></h3><p>Verifies: a rebalance really happens (log line <code>[rebalance] joined ... claims=demo-topic[0 1 2]</code>); offsets are committed (<code>lag</code> drops accordingly); the limit is exact; manual commits work.</p><p><strong>Why the limit must be exact</strong>: this is a real bug scene. The first version checked <code>count &lt; limit</code> per partition; with three partitions in parallel, <code>--limit 6</code> consumed 9. The fix puts &quot;check and increment&quot; under one lock (<code>tryAcquire</code>); a partition that cannot get a slot returns immediately <strong>without <code>MarkMessage</code></strong>, so its offset does not advance and the record can be read again. &quot;Consumed less&quot; never becomes &quot;lost data&quot;: after <code>--limit 6</code> the committed offsets are 2+3+1=6, and lag drops by exactly 6.</p><p><strong>Why <code>Consume</code> must sit in a loop</strong>: it returns normally on every rebalance. Calling it once means the first instance &quot;stops consuming&quot; as soon as another member joins — the classic consumer group trap. The loop lives in <code>kafkax.ConsumeGroup</code>, so the command layer calls it once and cannot forget it.</p><h3 id="lag" tabindex="-1"><code>lag</code> <a class="header-anchor" href="#lag" aria-label="Permalink to &quot;\`lag\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== Consumer lag group=demo-group topic=demo-topic ==</span></span>
<span class="line"><span>  PARTITION  COMMITTED  END  LAG</span></span>
<span class="line"><span>  0          3          217  214</span></span>
<span class="line"><span>  1          2          73   71</span></span>
<span class="line"><span>  2          1          102  101</span></span>
<span class="line"><span>  total lag: 386 records</span></span></code></pre></div><p><code>Committed</code> comes from <code>OffsetFetch</code>, <code>End</code> from <code>ListOffsets(Newest)</code>; the difference is the backlog. <code>Committed = -1</code> means nothing was ever committed.</p><p><strong>Why it matters</strong>: &quot;is consumption keeping up&quot; has exactly one reliable signal. Logs tell you what was processed, not how much is left.</p><p>Implementation trap: after <code>OffsetFetch</code> v8 the response structure changed from <code>Blocks</code> to <code>Groups</code>; you must use <code>resp.GetBlock(topic, partition)</code>.</p><h3 id="groups" tabindex="-1"><code>groups</code> <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;\`groups\`&quot;">​</a></h3><p>Verifies whether a group exists, its state (<code>Stable</code> / <code>Empty</code> / <code>PreparingRebalance</code> / <code>CompletingRebalance</code>), and member count.</p><p><strong>Why</strong>: <code>Empty</code> is normal — offsets survive the process (7 days by default, <code>offsets.retention.minutes</code>). Knowing this prevents the wrong conclusion &quot;the group is gone, so the offsets are gone too&quot;.</p><h3 id="e2e" tabindex="-1"><code>e2e</code> <a class="header-anchor" href="#e2e" aria-label="Permalink to &quot;\`e2e\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>go run . e2e                          # create a temporary topic, delete it afterwards</span></span>
<span class="line"><span>go run . e2e --messages 500           # more data</span></span>
<span class="line"><span>go run . e2e --topic my-topic --keep  # reuse a topic you name, and keep it</span></span></code></pre></div><p>It is a <strong>smoke test</strong>: any failing step exits non-zero, so it fits CI. Topic selection: without <code>--topic</code> it generates <code>demo-e2e-&lt;nanotimestamp&gt;</code> and deletes it; with <code>--topic</code> it reuses yours and <strong>does not delete it</strong> (so it cannot destroy your data).</p><h2 id="the-seven-e2e-assertions" tabindex="-1">The seven e2e assertions <a class="header-anchor" href="#the-seven-e2e-assertions" aria-label="Permalink to &quot;The seven e2e assertions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Assertion</th><th>Why it must be there</th></tr></thead><tbody><tr><td>1 connect</td><td>Brokers discoverable, controller available</td><td>Without metadata nothing else matters</td></tr><tr><td>2 topic</td><td>Metadata visible after create (or reuse)</td><td>Covers the asynchronous creation timing trap</td></tr><tr><td>3 produce</td><td>All N records acknowledged</td><td>Covers compression, idempotence and <code>acks=all</code> end to end</td></tr><tr><td>4 partition</td><td>The same key maps to the same partition</td><td>The premise of ordering holds</td></tr><tr><td>5 consume</td><td>All N records received, per-partition offsets strictly increasing</td><td>No duplicates, no gaps, no reordering</td></tr><tr><td>6 offsets</td><td>Lag back to baseline (0 for a new topic)</td><td>Offsets were really committed; using a baseline instead of a hard-coded 0 allows reuse on a non-empty topic</td></tr><tr><td>7 cleanup</td><td>Temporary group deleted; topic kept or deleted by <code>--keep</code></td><td>Repeatable without polluting the cluster</td></tr></tbody></table><p>Two details in step 5:</p><ul><li>Ordering: each partition remembers &quot;the previous offset&quot; and the next record must be strictly greater — a duplicate or a reorder fails immediately;</li><li>Completion: the check <strong>cannot rely on the context alone</strong>; the limit only fires when &quot;the next record arrives&quot;, so once N are received with no further records <code>OnLimit</code> never triggers — hence polling the consumed count instead.</li></ul><h2 id="code-walkthrough" tabindex="-1">Code walkthrough <a class="header-anchor" href="#code-walkthrough" aria-label="Permalink to &quot;Code walkthrough&quot;">​</a></h2><p>Paths are relative to <code>public/demos/kafka/</code>.</p><p><strong>Safety switches set from the start</strong>: <code>Version=3.9.0.0</code> aligned with the broker; <code>RequiredAcks=WaitForAll</code>; <code>Idempotent=true</code> together with <code>MaxOpenRequests=1</code> (a hard requirement); <code>Offsets.Initial=OffsetOldest</code>.</p><p><strong>Headers on every record</strong>: <code>source</code> and <code>seq</code>, proving headers survive the round trip — a step many pipeline checks forget.</p><p><strong>Async production must drain both channels</strong>: <code>Successes()</code> and <code>Errors()</code>. Not reading them blocks the internal channels and grows memory.</p><p><strong>Offset semantics</strong>: <code>MarkMessage</code> only marks locally; durability comes from the commit. Auto-commit plus a failed handler can lose records; manual commit after success gives at-least-once, with possible duplicates that need idempotent handling.</p><p><strong>Commit once more before exiting</strong>: with <code>--commit-every 5</code> and only 7 records consumed, the last 2 are consumed again unless committed; <code>Cleanup</code> commits once more.</p><p><strong>Output and parsing in one place</strong>: <code>WriteMessage</code> / <code>ParseOffset</code> translate <code>oldest</code> to <code>-2</code> and <code>newest</code> to <code>-1</code>, so the command layer never remembers magic numbers.</p><h2 id="measured-run" tabindex="-1">Measured run <a class="header-anchor" href="#measured-run" aria-label="Permalink to &quot;Measured run&quot;">​</a></h2><p>Real output on this machine (single Docker broker, Go 1.25, small records):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== Cluster health ==</span></span>
<span class="line"><span>  client addresses   : localhost:9092</span></span>
<span class="line"><span>  negotiated version : 3.9.0</span></span>
<span class="line"><span>  metadata refresh   : OK (4ms)</span></span>
<span class="line"><span>  brokers            : 1</span></span>
<span class="line"><span>  controller         : broker#1 localhost:9092</span></span>
<span class="line"><span>  topics             : 2 (including internal topics like __consumer_offsets)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>========== End-to-end verification  topic=demo-e2e-... messages=30 ==========</span></span>
<span class="line"><span>Step 1/7 connect to the cluster</span></span>
<span class="line"><span>  [PASS] brokers discovered       1 found, addresses [localhost:9092]</span></span>
<span class="line"><span>  [PASS] controller available     broker#1 localhost:9092</span></span>
<span class="line"><span>Step 2/7 prepare topic (demo-e2e-...)</span></span>
<span class="line"><span>  created topic with 3 partitions, replication factor 1</span></span>
<span class="line"><span>  [PASS] topic visible            partitions=3</span></span>
<span class="line"><span>Step 3/7 produce 30 records (3 rotating keys)</span></span>
<span class="line"><span>  [PASS] records acked            30/30 records, took 56ms</span></span>
<span class="line"><span>Step 4/7 verify the same key maps to the same partition</span></span>
<span class="line"><span>  [PASS] key-partition stable     mapping map[user-0:1 user-1:0 user-2:0]</span></span>
<span class="line"><span>Step 5/7 consume with group demo-e2e-group-...</span></span>
<span class="line"><span>  collected all 30 records</span></span>
<span class="line"><span>  [PASS] records consumed         got 30, want 30</span></span>
<span class="line"><span>  [PASS] offsets monotonic        last offset per partition map[0:19 1:9]</span></span>
<span class="line"><span>Step 6/7 verify offsets are committed and lag is back to baseline</span></span>
<span class="line"><span>  [PASS] lag back to baseline     total lag 0 (baseline 0)</span></span>
<span class="line"><span>Step 7/7 cleanup</span></span>
<span class="line"><span>  deleted group demo-e2e-group-...</span></span>
<span class="line"><span>  deleted topic demo-e2e-...</span></span></code></pre></div><p>The produce side shows the sync/async gap too:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> produce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --messages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # sync, around 400 records/s</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> produce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --async</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --messages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # async, around 13,000 records/s</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>How to check</th></tr></thead><tbody><tr><td>Every command cannot connect</td><td>Container not running / port not published</td><td><code>./scripts/kafka.sh status</code></td></tr><tr><td>Connects but hangs forever</td><td><code>ADVERTISED_LISTENERS</code> points inside the container</td><td>See the advertised settings in part one</td></tr><tr><td><code>create</code> succeeds but <code>describe</code> says it does not exist</td><td>Asynchronous creation</td><td>The project polls with <code>WaitTopicVisible</code>; check <code>topic list</code> manually</td></tr><tr><td><code>NOT_LEADER_FOR_PARTITION</code></td><td>Stale metadata</td><td>The project refreshes metadata per topic first; <code>Metadata.Retry.Max=5</code> is the fallback</td></tr><tr><td>A group suddenly &quot;stops consuming&quot;</td><td><code>Consume</code> not called again after a rebalance</td><td>Confirm the loop inside <code>ConsumeGroup</code></td></tr><tr><td><code>lag</code> shows <code>none</code></td><td>The group never committed on that partition</td><td>Normal; the whole partition counts as unconsumed</td></tr><tr><td>Fewer records than expected</td><td>Keys hash into few partitions</td><td><code>topic describe</code> shows the distribution</td></tr><tr><td>Records repeat after manual commits</td><td>The tail was never committed</td><td>Check whether <code>Cleanup</code> commits once more</td></tr><tr><td><code>e2e</code> fails on an existing topic</td><td>It asserted 0 while the baseline was non-zero</td><td>Assert &quot;back to baseline&quot;, not &quot;lag=0&quot;</td></tr></tbody></table><h2 id="production-checklist" tabindex="-1">Production checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Demo</th><th>Production</th></tr></thead><tbody><tr><td>Replication factor</td><td>1</td><td>3 (<code>min.insync.replicas=2</code>)</td></tr><tr><td>Auto topic creation</td><td>true</td><td>false; created by the platform</td></tr><tr><td>acks</td><td>all</td><td>all</td></tr><tr><td>Idempotence / transactions</td><td>Idempotence on</td><td>Transactions when atomic writes span partitions</td></tr><tr><td>Security</td><td>PLAINTEXT</td><td>SASL_SSL / mTLS</td></tr><tr><td>Monitoring</td><td>None</td><td>Lag, ISR shrinkage, UnderReplicatedPartitions, disk usage</td></tr><tr><td>Partitions</td><td>3</td><td>Planned from peak throughput and parallelism; resizing later breaks the key mapping</td></tr><tr><td>Retention</td><td>7 days</td><td>Based on value and capacity; tiered storage when needed</td></tr></tbody></table><p>Reliability is the combination of &quot;replicas + acks + idempotence/transactions + consumer-side idempotence&quot;; leave one out and &quot;no loss, no duplicates&quot; does not hold.</p><h2 id="cleanup" tabindex="-1">Cleanup <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;Cleanup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/kafka.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # stop the container, keep the data volume</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/kafka.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # remove the container and the volume</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # build output</span></span></code></pre></div><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://kafka.apache.org/documentation/" target="_blank" rel="noreferrer">Apache Kafka documentation</a></li><li><a href="https://kafka.apache.org/documentation/#kraft" target="_blank" rel="noreferrer">KRaft mode (no ZooKeeper)</a></li><li><a href="https://github.com/IBM/sarama" target="_blank" rel="noreferrer">sarama: the Go client used here</a></li><li><a href="https://github.com/twmb/franz-go" target="_blank" rel="noreferrer">franz-go: another popular Go client</a></li><li><a href="https://github.com/spf13/cobra" target="_blank" rel="noreferrer">cobra: the CLI framework</a></li></ul><p>Code and scripts: <a href="https://github.com/zq-xu/zq-xu.github.io/tree/master/public/demos/kafka" target="_blank" rel="noreferrer">public/demos/kafka</a> · Back to <a href="./introduction.html">part one: Kafka in brief, and running it locally</a> · <a href="./">series index</a></p>`,83)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
